head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > P > accessibility]<br/>DatePicker 컴포넌트의 키보드 접근성을 활성화 할지 설정합니다.",
    "validation" : [
        "true 설정 시 DatePicker 컴포넌트의 키보드 접근성을 활성화합니다.",
        "true 설정 시 각 스핀 컬럼에 WAI-ARIA 속성(role, aria-valuenow, aria-valuetext, aria-valuemin, aria-valuemax, aria-label)이 설정됩니다.",
        "true 설정 시 위/아래 방향키로 값을 변경할 수 있습니다.",
        "false (default) 설정 시 키보드 접근성을 비활성화합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),
        calendarValueType : "yearMonthDate"
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);
}



scwin.getAccessibilityOption = function () {
    let isOn = (target1.options.accessibility === true);

    // validation: true 설정 시 DatePicker 컴포넌트의 키보드 접근성을 활성화 / false (default) 설정 시 비활성화
    wf_body_bottom.getObj("scwin").setReturnValue("[키보드 접근성 활성화 여부] " + (isOn ? "활성화됨" : "비활성화됨") + " (accessibility=" + target1.options.accessibility + ")");
}



scwin.getAriaInfo = function () {
    // validation: 각 스핀 컬럼에 WAI-ARIA 속성(role, aria-valuenow, aria-valuetext, aria-valuemin, aria-valuemax, aria-label) 설정
    // childControlList: 각 스핀 컬럼 (연/월/일)
    let columnLabels = ['연', '월', '일'];
    let foundAny = false;

    if (target1.childControlList && target1.childControlList.length > 0) {
        for (let i = 0; i < target1.childControlList.length; i++) {
            let col = target1.childControlList[i];
            if (!col || !col.dom || !col.dom.itembox) continue;

            // ARIA 속성은 컬럼 내 한 셀(현재 포커스 대상)에만 부여되므로 role='spinbutton' 부여 셀을 탐색
            let childNodes = col.dom.itembox.childNodes;
            let ariaNode = null;
            for (let j = 0; j < childNodes.length; j++) {
                if (childNodes[j].getAttribute && childNodes[j].getAttribute('role') === 'spinbutton') {
                    ariaNode = childNodes[j];
                    break;
                }
            }

            let label = columnLabels[i] || ('col' + i);

            if (!ariaNode) {
                wf_body_bottom.getObj("scwin").setReturnValue("[" + label + " 컬럼 WAI-ARIA 적용 여부] 미적용 (role='spinbutton' 셀 없음)");
                foundAny = true;
                continue;
            }

            let role = ariaNode.getAttribute('role');
            let ariaValueNow = ariaNode.getAttribute('aria-valuenow');
            let ariaValueText = ariaNode.getAttribute('aria-valuetext');
            let ariaValueMin = ariaNode.getAttribute('aria-valuemin');
            let ariaValueMax = ariaNode.getAttribute('aria-valuemax');
            let ariaLabel = ariaNode.getAttribute('aria-label');

            let allApplied = (role !== null && ariaValueNow !== null && ariaValueText !== null
                && ariaValueMin !== null && ariaValueMax !== null && ariaLabel !== null);

            wf_body_bottom.getObj("scwin").setReturnValue("[" + label + " 컬럼 WAI-ARIA 적용 여부] " + (allApplied ? "모두 적용됨" : "미적용 또는 누락")
                + " (role=" + role + ", aria-valuenow=" + ariaValueNow + ", aria-valuetext=" + ariaValueText
                + ", aria-valuemin=" + ariaValueMin + ", aria-valuemax=" + ariaValueMax + ", aria-label=" + ariaLabel + ")");
            foundAny = true;
        }
    }

    if (!foundAny) {
        wf_body_bottom.getObj("scwin").setReturnValue("[스핀 컬럼 WAI-ARIA 적용 여부] 스핀 컬럼 정보 없음");
    }
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getAccessibilityOption();
    scwin.getAriaInfo();
}
